import React from 'react';
import { StyleSheet, View, Text, ScrollView } from 'react-native';
import ShiftCard from './ShiftCard';
import { weeklyShifts, timeSlots, daysOfWeek } from '../data/weeklyShiftsData';

// Constants for precise calculations
const TIME_SLOT_HEIGHT = 60;
const TOTAL_TIME_SLOTS = timeSlots.length;

const WeeklyGrid = ({ selectedDate }) => {
  const renderTimeSlot = (time) => {
    return (
      <View key={time} style={styles.timeSlot}>
        <Text style={styles.timeText}>{time}</Text>
        {/* Không cần timeLine riêng, sẽ dùng horizontal lines chung */}
      </View>
    );
  };

  const renderDayColumn = (day) => {
    const shifts = weeklyShifts[day] || [];
    
    return (
      <View key={day} style={styles.dayColumn}>
        {shifts.map((shift) => {
          // Tính toán vị trí chính xác dựa trên thời gian
          const startTime = shift.startTime;
          const endTime = shift.endTime;
          
          // Tìm index của startTime trong timeSlots
          const startIndex = timeSlots.indexOf(startTime);
          const endIndex = timeSlots.indexOf(endTime);
          
          // Tính toán vị trí và chiều cao
          const top = startIndex * TIME_SLOT_HEIGHT;
          const height = (endIndex - startIndex) * TIME_SLOT_HEIGHT;
          
          return (
            <View 
              key={shift.id} 
              style={[
                styles.shiftContainer,
                { 
                  top: top,
                  height: height
                }
              ]}
            >
              <ShiftCard shift={shift} />
            </View>
          );
        })}
      </View>
    );
  };

  const renderGridLines = () => {
    return timeSlots.map((time, index) => (
      <View key={`line-${index}`} style={styles.gridLine} />
    ));
  };

  const renderHorizontalLines = () => {
    // Tạo lines cho tất cả time slots để đảm bảo kích thước đều
    return timeSlots.map((time, index) => {
      // Tính toán chính xác vị trí từ điểm đầu tiên của khung
      const topPosition = (index + 1) * TIME_SLOT_HEIGHT;
      
      return (
        <View 
          key={`horizontal-${index}`} 
          style={[
            styles.horizontalTimeLine,
            { top: topPosition }
          ]} 
        />
      );
    });
  };

  return (
    <View style={styles.container}>
      <ScrollView 
        style={styles.scrollContainer}
        showsVerticalScrollIndicator={false}
        bounces={false}
      >
        <View style={styles.gridContainer}>
          {/* Time Axis */}
          <View style={styles.timeAxis}>
            {timeSlots.map(renderTimeSlot)}
          </View>

          {/* Days Columns */}
          <View style={styles.daysContainer}>
            {daysOfWeek.map(renderDayColumn)}
          </View>

          {/* Grid Lines */}
          <View style={styles.gridLinesContainer}>
            {renderGridLines()}
          </View>

          {/* Horizontal Lines */}
          <View style={styles.horizontalLinesContainer}>
            {renderHorizontalLines()}
          </View>
        </View>
      </ScrollView>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#ffffff',
    borderTopWidth: 1,
    borderTopColor: '#E0E0E0',
  },
  scrollContainer: {
    flex: 1,
  },
  gridContainer: {
    flexDirection: 'row',
    width: '100%',
    position: 'relative',
    // Đảm bảo chiều cao phù hợp với tất cả time slots
    minHeight: TIME_SLOT_HEIGHT * TOTAL_TIME_SLOTS,
  },
  timeAxis: {
    width: 60,
    backgroundColor: '#FFFFFF', // Google Calendar white background
    paddingVertical: 0, // Bỏ padding để đảm bảo kích thước chính xác
    borderRightWidth: 1,
    borderRightColor: '#E8EAED', // Google Calendar border color
    // Đảm bảo kích thước cố định
    minHeight: TIME_SLOT_HEIGHT * TOTAL_TIME_SLOTS,
  },
  timeSlot: {
    height: TIME_SLOT_HEIGHT,
    justifyContent: 'center',
    alignItems: 'center',
    // Bỏ borderBottom để dùng horizontal lines chung
    position: 'relative',
    // Đảm bảo kích thước chính xác - cố định không thay đổi
    minHeight: TIME_SLOT_HEIGHT,
    maxHeight: TIME_SLOT_HEIGHT,
    // Căn giữa text trong ô
    textAlign: 'center',
    // Đảm bảo không có padding thừa
    paddingVertical: 0,
    paddingHorizontal: 0,
  },
  timeText: {
    fontSize: 12,
    color: '#666666',
    fontWeight: '500',
    textAlign: 'center',
    // Đảm bảo text căn giữa hoàn hảo
    lineHeight: 16,
  },
  daysContainer: {
    flexDirection: 'row',
    flex: 1,
  },
  dayColumn: {
    flex: 1,
    backgroundColor: '#FFFFFF', // Google Calendar white
    borderRightWidth: 1,
    borderRightColor: '#E8EAED', // Google Calendar border
    paddingHorizontal: 2,
    paddingVertical: 8,
    position: 'relative',
    // Đảm bảo kích thước chính xác cho mỗi time slot
    minHeight: TIME_SLOT_HEIGHT * TOTAL_TIME_SLOTS,
    zIndex: 5, // Layer giữa
  },
  shiftContainer: {
    position: 'absolute',
    left: 2,
    right: 2,
    zIndex: 10, // Layer trên cùng
    // top và height sẽ được set dynamically
  },
  gridLinesContainer: {
    position: 'absolute',
    top: 0,
    left: 60,
    right: 0,
    bottom: 0,
    flexDirection: 'row',
  },
  horizontalLinesContainer: {
    position: 'absolute',
    top: 0,
    left: 0, // Start from time axis
    right: 0,
    bottom: 0,
    zIndex: 1, // Layer dưới cùng
  },
  horizontalTimeLine: {
    position: 'absolute',
    left: 0,
    right: 0,
    height: 1,
    backgroundColor: '#E8EAED', // Google Calendar color
    // Google Calendar style - solid lines
    zIndex: 0, // Layer dưới cùng
  },
});

export default WeeklyGrid;
